import{_ as i,o,c as a,a0 as l,j as e,a as d}from"./chunks/framework.DzvPB4Y-.js";const f=JSON.parse('{"title":"一维装箱（BPP1D）：适用问题与学习路线","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/bpp1d/index.md","filePath":"zh-cn/frameworks/bpp1d/index.md"}'),n={name:"zh-cn/frameworks/bpp1d/index.md"},r={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},c={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.025ex"},xmlns:"http://www.w3.org/2000/svg",width:"1.357ex",height:"1.025ex",role:"img",focusable:"false",viewBox:"0 -442 600 453","aria-hidden":"true"},s={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},p={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.186ex"},xmlns:"http://www.w3.org/2000/svg",width:"5.254ex",height:"1.692ex",role:"img",focusable:"false",viewBox:"0 -666 2322.4 748","aria-hidden":"true"};function h(m,t,u,b,g,T){return o(),a("div",null,[t[9]||(t[9]=l('<h1 id="一维装箱-bpp1d-适用问题与学习路线" tabindex="-1">一维装箱（BPP1D）：适用问题与学习路线 <a class="header-anchor" href="#一维装箱-bpp1d-适用问题与学习路线" aria-label="Permalink to &quot;一维装箱（BPP1D）：适用问题与学习路线&quot;">​</a></h1><p>已有一批长条物品，要放进有限长度的容器，例如型材定尺装载。每种容器类型有长度、承重、费用和可用库存；相邻物品可能需要间距。BPP1D 帮你选择装载组合，并生成可复核的放置结果。本模块统一将 <code>Bin</code> 称为“容器”、<code>BinType</code> 称为“容器类型”。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>角色</th><th>核心字段</th></tr></thead><tbody><tr><td>物品</td><td><code>Item</code></td><td>输入</td><td><code>id</code>、<code>length</code>、<code>weight</code>、精确件数 <code>amount</code></td></tr><tr><td>容器类型</td><td><code>BinType</code></td><td>输入</td><td>长度、承重、<code>cost</code>、可选 <code>inventory</code></td></tr><tr><td>问题</td><td><code>PackingProblem</code></td><td>输入</td><td>物品、容器类型、<code>spacing</code>、<code>objective</code></td></tr><tr><td>装载组合</td><td><code>PackingPattern</code></td><td>中间概念</td><td>容器类型 ID、每种物品的件数；尚未展开坐标</td></tr><tr><td>求解结果</td><td><code>Bpp1dSolution</code></td><td>输出</td><td>状态/报告、候选完整性、列数、<code>packing</code></td></tr><tr><td>放置结果</td><td><code>PackingResult</code></td><td>输出</td><td><code>plans</code>、空闲/尾部余量区间、物品汇总</td></tr><tr><td>指标</td><td><code>PackingKpi</code></td><td>输出</td><td>容器数、件数、消耗容器长度、尾部余量长度、利用率、费用</td></tr></tbody></table>',4)),e("p",null,[t[4]||(t[4]=d("间距（",-1)),t[5]||(t[5]=e("code",null,"spacing",-1)),t[6]||(t[6]=d("）仅存在于同一个容器的相邻物品之间，容器首尾不额外计入间距，即装入 ",-1)),e("mjx-container",r,[(o(),a("svg",c,[...t[0]||(t[0]=[e("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[e("g",{"data-mml-node":"math"},[e("g",{"data-mml-node":"mi"},[e("path",{"data-c":"1D45B",d:"M21 287Q22 293 24 303T36 341T56 388T89 425T135 442Q171 442 195 424T225 390T231 369Q231 367 232 367L243 378Q304 442 382 442Q436 442 469 415T503 336T465 179T427 52Q427 26 444 26Q450 26 453 27Q482 32 505 65T540 145Q542 153 560 153Q580 153 580 145Q580 144 576 130Q568 101 554 73T508 17T439 -10Q392 -10 371 17T350 73Q350 92 386 193T423 345Q423 404 379 404H374Q288 404 229 303L222 291L189 157Q156 26 151 16Q138 -11 108 -11Q95 -11 87 -5T76 7T74 17Q74 30 112 180T152 343Q153 348 153 366Q153 405 129 405Q91 405 66 305Q60 285 60 284Q58 278 41 278H27Q21 284 21 287Z",style:{"stroke-width":"3"}})])])],-1)])])),t[1]||(t[1]=e("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[e("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[e("mi",null,"n")])],-1))]),t[7]||(t[7]=d(" 件物品产生 ",-1)),e("mjx-container",s,[(o(),a("svg",p,[...t[2]||(t[2]=[l('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math"><g data-mml-node="mi"><path data-c="1D45B" d="M21 287Q22 293 24 303T36 341T56 388T89 425T135 442Q171 442 195 424T225 390T231 369Q231 367 232 367L243 378Q304 442 382 442Q436 442 469 415T503 336T465 179T427 52Q427 26 444 26Q450 26 453 27Q482 32 505 65T540 145Q542 153 560 153Q580 153 580 145Q580 144 576 130Q568 101 554 73T508 17T439 -10Q392 -10 371 17T350 73Q350 92 386 193T423 345Q423 404 379 404H374Q288 404 229 303L222 291L189 157Q156 26 151 16Q138 -11 108 -11Q95 -11 87 -5T76 7T74 17Q74 30 112 180T152 343Q153 348 153 366Q153 405 129 405Q91 405 66 305Q60 285 60 284Q58 278 41 278H27Q21 284 21 287Z" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(822.2,0)"><path data-c="2212" d="M84 237T84 250T98 270H679Q694 262 694 250T679 230H98Q84 237 84 250Z" style="stroke-width:3;"></path></g><g data-mml-node="mn" transform="translate(1822.4,0)"><path data-c="31" d="M213 578L200 573Q186 568 160 563T102 556H83V602H102Q149 604 189 617T245 641T273 663Q275 666 285 666Q294 666 302 660V361L303 61Q310 54 315 52T339 48T401 46H427V0H416Q395 3 257 3Q121 3 100 0H88V46H114Q136 46 152 46T177 47T193 50T201 52T207 57T213 61V578Z" style="stroke-width:3;"></path></g></g></g>',1)])])),t[3]||(t[3]=e("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[e("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[e("mi",null,"n"),e("mo",null,"−"),e("mn",null,"1")])],-1))]),t[8]||(t[8]=d(" 个间距。",-1))]),t[10]||(t[10]=l('<div class="tip custom-block"><p class="custom-block-title">单位与库存</p><p>长度和重量保留物理单位。Kotlin 通过适配器转换兼容单位；Rust 本课在输入时统一为 m/kg。<code>inventory = null</code>（Kotlin）/ <code>None</code>（Rust）表示不限库存，<code>0</code> / <code>Some(0)</code> 表示不能使用。</p></div><h3 id="从返回值定位业务字段" tabindex="-1">从返回值定位业务字段 <a class="header-anchor" href="#从返回值定位业务字段" aria-label="Permalink to &quot;从返回值定位业务字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>想读取什么</th><th>Kotlin</th><th>Rust</th></tr></thead><tbody><tr><td>候选是否枚举完整</td><td><code>solution.candidateComplete</code></td><td><code>solution.candidate_complete</code></td></tr><tr><td>启用的容器</td><td><code>solution.packing.plans</code></td><td><code>solution.packing.as_ref()</code> 后读 <code>plans</code></td></tr><tr><td>容器及容器类型</td><td><code>plan.bin.id</code>、<code>plan.bin.type</code></td><td><code>plan.bin_id</code>、<code>plan.bin_type_id</code>，按 ID 查 <code>context.problem().bin_types</code></td></tr><tr><td>物品区间</td><td><code>placement.itemId</code>、<code>start</code>、<code>start + length</code></td><td><code>placement.item_id</code>、<code>start</code>、<code>length</code></td></tr><tr><td>尾部余量 / 空闲区间</td><td><code>packing.remnants</code>（尾部余量）；相邻放置可推导间隙</td><td><code>packing.free_intervals</code>（含内部间隙和尾部余量）</td></tr><tr><td>核心 KPI</td><td><code>packing.kpi(Meter)</code></td><td><code>context.kpi(&amp;packing)</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">两种语言的结果边界</p><p>Kotlin 返回成功结果后直接读取 <code>packing</code>；Rust 的 <code>packing</code> 是 <code>Option</code>，没有找到可行解时先读取 <code>report</code>。两者的 KPI <code>remnantLength</code> / <code>remnant_length</code> 都只统计尾部余量，不包含物品间距。生成器的 <code>complete</code> 对应求解结果中的候选完整性字段，<strong>不代表已证明整数最优</strong>。</p></div><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>适用场景</th><th>如何判断是否合适</th></tr></thead><tbody><tr><td><code>Bpp1dMilp</code></td><td>首次接入、小型实例，或生成后的候选集合可以直接交给整数主问题</td><td>先用它建立正确性和耗时的对照基准，观察候选完整性与列数</td></tr><tr><td><code>Bpp1dColumnGeneration</code></td><td>需要观察 LP 定价过程，或比较分轮激活候选列的表现</td><td>在同一数据、生成预算和后端下比较耗时、列数和报告</td></tr></tbody></table><p>当前两个入口都会先生成<strong>有界的有限候选集合</strong>；列生成从这个集合中搜索并选择可改进目标的候选，最终整数阶段使用生成列与初始候选列的合并集合。它不是绕过枚举的无限规模入口，因此没有通用的“超过多少件就切换”阈值。先用代表性数据测量，再选择入口。</p><p>Kotlin 向构造函数注入 <code>ColumnGenerationSolver</code> 和数值适配器；Rust 向 <code>solve</code> 注入求解器回调。LP、MILP 和定价的含义见<a href="./../#terminology">术语说明</a>；切换方式与节点数、候选列数、每轮列数的配置见<a href="./business-scenario.html#column-generation">第二课的列生成示例</a>。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>这是已有物品的装载模型。需要原料加工、产品产出和超欠产时，比较 <a href="./../csp1d/">CSP1D</a>。</li><li>候选枚举可能受节点数和候选数限制；<code>complete</code> 是需要读取的结果，不是默认假定。</li><li>LP 定价结束不等于整数最优；有限候选集合内最优也不自动等于全局最优。</li><li>最后几个容器的重新装载必须复核完整方案，不能把只适用于全局的业务规则直接当成局部子问题规则。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-packing.html">第一次一维装箱</a>，学习输入、求解、放置和数量复核。</li><li>在同一场景里增加间距、库存、多容器类型和费用，再阅读扩展接口。</li><li>需要自己建模时，参考<a href="/ospf/zh-cn/guide/modeling-workflow.html">建模流程</a>，不要在应用服务里复制已有领域公式。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp1d/README_ch.md" target="_blank" rel="noreferrer">Kotlin API 与扩展接口</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp1d/README_ch.md" target="_blank" rel="noreferrer">Rust API 与扩展接口</a></li><li><a href="/ospf/zh-cn/guide/solving-results.html">理解求解结果</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./first-packing.html">第一次一维装箱：物品、间距与库存</a>。完成后再学<a href="./business-scenario.html">多容器类型、库存与费用</a>，并按<a href="./../integration.html">业务接入检查</a>迁入自己的应用。</p>',17))])}const Q=i(n,[["render",h]]);export{f as __pageData,Q as default};
